private static void spawnInfinityDrops(Level level, BlockPos pos, FireCraftingRecipe recipe) {
        var randomSource = level.getRandom();
        boolean didDrop = false;

        for (var result : recipe.results()) {
            float dropChance = level.getRandom().nextFloat();
            if (dropChance >= result.chance()) {
                continue;
            }

            int itemCount = level.getRandom().nextIntBetweenInclusive(result.minCount(), result.maxCount());
            if (itemCount <= 0) {
                continue;
            }

            ItemStack resultStack = result.result().copy();
            resultStack.setCount(itemCount);

            // Get random offset
            double x = randomSource.nextFloat() * 0.5f + 0.25f;
            double y = randomSource.nextFloat() * 0.5f + 0.25f;
            double z = randomSource.nextFloat() * 0.5f + 0.25f;
            ItemEntity itemEntity = new ItemEntity(level, pos.getX() + x, pos.getY() + y, pos.getZ() + z, resultStack);
            itemEntity.setDefaultPickUpDelay();

            // Make it survive the fire for a bit
            itemEntity.hurt(itemEntity.damageSources().inFire(), -100);

            // Actually set it on fire
            itemEntity.setRemainingFireTicks(10);
            level.addFreshEntity(itemEntity);
            didDrop = true;
        }

        if (didDrop) {
            // Play explosion sound
            if (BaseConfig.COMMON.INFINITY.MAKES_SOUND.get()) {
                level.playSound(null, pos, SoundEvents.FIREWORK_ROCKET_LARGE_BLAST, SoundSource.BLOCKS, 1.0f,
                    randomSource.nextFloat() * 0.4f + 0.8f);
            }

            // Replace the base (if applicable)
            if (recipe.blockAfterBurning().isPresent()) {
                level.setBlock(pos.below(), recipe.blockAfterBurning().get().defaultBlockState(), Block.UPDATE_ALL);
            }
        }
    }

public boolean tryPerformFireCrafting(Level level, BlockPos pos) {
        FireCraftingRecipe matchingRecipe = getMatchingRecipe(level, pos);

        if (matchingRecipe == null) {
            return false;
        }

        spawnInfinityDrops(level, pos, matchingRecipe);
        return true;
    }

@Nullable
    public FireCraftingRecipe getMatchingRecipe(Level level, BlockPos pos) {
        BlockState blockBelow = level.getBlockState(pos.below());

        for (var recipeHolder : getRecipes(level)) {
            var recipe = recipeHolder.value();
            if (recipe.isBaseValid(blockBelow.getBlock()) && recipe.isDimensionValid(level.dimension())) {
                return recipe;
            }
        }

        return null;
    }

public List<RecipeHolder<FireCraftingRecipe>> getRecipes(Level level) {
        if (level.getRecipeManager() != cachedRecipeManager.get()) {
            cachedRecipeManager = new WeakReference<>(level.getRecipeManager());
            cachedRecipes = level.getRecipeManager().getAllRecipesFor(EIORecipes.FIRE_CRAFTING.type().get());
        }

        return cachedRecipes;
    }

@UseOnly(LogicalSide.SERVER)
    private void onRandomTick(ServerLevel level, BlockPos pos) {
        // Get the ticked block state
        BlockState tickedBlockState = level.getBlockState(pos);

        // Ensure that we should process this block
        boolean isFire = tickedBlockState.is(BlockTags.FIRE);
        if (!isFire && !fireTracker.containsKey(pos)) {
            return;
        }

        // Find a potential recipe for this fire block.
        var matchingRecipe = getMatchingRecipe(level, pos);
        if (matchingRecipe == null) {
            // No recipe found, remove the fire block from tracking.
            fireTracker.remove(pos);
            return;
        }

        long gameTime = level.getGameTime();

        // If it's still fire, it should be tracked.
        // If it has been extinguished, it should 'pop'.
        if (isFire) {
            // Prune the oldest fires if we have too many in the tracker.
            int maxTracked = BaseConfig.COMMON.INFINITY.MAX_TRACKED_FIRES.get();
            int excess = fireTracker.size() - maxTracked;
            if (excess > 0) {
                // Remove the oldest fires (smallest expiration time first) until within the max
                var toRemove = fireTracker.entrySet().stream()
                    .sorted(Map.Entry.comparingByValue())
                    .limit(excess)
                    .map(Map.Entry::getKey)
                    .toList();

                toRemove.forEach(fireTracker::remove);
            }

            fireTracker.putIfAbsent(pos, gameTime + BaseConfig.COMMON.INFINITY.FIRE_MIN_AGE.get());
        } else {
            if (level.getBlockState(pos).isAir() && gameTime > fireTracker.get(pos)) {
                spawnInfinityDrops(level, pos, matchingRecipe);
            }

            fireTracker.remove(pos);
        }
    }

@SubscribeEvent
    public static void onNeighborNotifyEvent(BlockEvent.NeighborNotifyEvent event) {
        if (event.getLevel() instanceof ServerLevel level) {
            var fireCraftingManager = level.getData(FireCraftingManager.ATTACHMENT_TYPE);
            fireCraftingManager.onRandomTick(level, event.getPos());
        }
    }

private void onWorldTick(ServerLevel level) {
        // Only run if fire tick is disabled.
        if (level.getGameRules().getBoolean(GameRules.RULE_DOFIRETICK)) {
            return;
        }

        // Create a list of positions that need to be turned to air. Fixes issues with
        // the fire tracker being modified while we iterate
        List<BlockPos> blocksToClear = new ArrayList<>();

        // Search for any fires that are due to spawn drops.
        long gameTime = level.getGameTime();
        for (Map.Entry<BlockPos, Long> fire : fireTracker.entrySet()) {
            BlockPos pos = fire.getKey();
            if (gameTime > fire.getValue()) {
                if (level.getBlockState(pos).getBlock() instanceof FireBlock) {
                    blocksToClear.add(pos);
                } else {
                    fireTracker.remove(fire.getKey());
                }
            }
        }

        // Turn them to air to trigger the usual event.
        for (BlockPos pos : blocksToClear) {
            level.setBlock(pos, Blocks.AIR.defaultBlockState(), Block.UPDATE_ALL);
        }
    }

@SubscribeEvent
    public static void onWorldTick(LevelTickEvent.Pre event) {
        if (event.getLevel() instanceof ServerLevel level) {
            var fireCraftingManager = level.getData(FireCraftingManager.ATTACHMENT_TYPE);
            fireCraftingManager.onWorldTick(level);
        }
    }

public boolean isBaseValid(Block block) {
        for (TagKey<Block> tag : baseTags) {
            if (block.defaultBlockState().is(tag)) {
                return true;
            }
        }
        return bases.contains(block);
    }

public boolean isDimensionValid(ResourceKey<Level> dimension) {
        return dimensions.contains(dimension);
    }

private int tick(IFluidHandlerItem storageFluidHandler, @Nullable Entity entity, Level level, BlockPos pos) {
		if (shouldInteractWithHand()) {
			if (entity instanceof Player player) {
				if (handleFluidContainerInHands(player, storageFluidHandler)) {
					lastHandActionTime = level.getGameTime();
					return HAND_INTERACTION_COOLDOWN_TIME;
				}
			} else if (handleFluidContainersInHandsOfNearbyPlayers(level, pos, storageFluidHandler)) {
				lastHandActionTime = level.getGameTime();
				return HAND_INTERACTION_COOLDOWN_TIME;
			}
		}
		return handleInWorldInteractions(storageFluidHandler, entity, level, pos)
				.orElseGet(() -> lastHandActionTime + 10 * HAND_INTERACTION_COOLDOWN_TIME > level.getGameTime()
						? HAND_INTERACTION_COOLDOWN_TIME
						: DID_NOTHING_COOLDOWN_TIME);
	}

@Override
	public void tick(@Nullable Entity entity, Level level, BlockPos pos) {
		if (isInCooldown(level)) {
			return;
		}
		setCooldown(level,
				storageWrapper.getFluidHandler().map(storageFluidHandler -> tick(storageFluidHandler, entity, level, pos)).orElse(DID_NOTHING_COOLDOWN_TIME));
	}

private Optional<Integer> handleInWorldInteractions(IFluidHandlerItem storageFluidHandler, @Nullable Entity entity, Level level, BlockPos pos) {
		if (shouldInteractWithWorld()) {
			Optional<Integer> newCooldown = interactWithWorld(level, pos, storageFluidHandler, entity);
			if (newCooldown.isPresent()) {
				return newCooldown;
			}
		}
		if (shouldInteractWithFluidHandlers()) {
			return interactWithAttachedFluidHandlers(level, pos, storageFluidHandler, entity instanceof Player player ? player : null);
		}
		return Optional.empty();
	}

private Optional<Integer> interactWithAttachedFluidHandlers(Level level, BlockPos pos, IFluidHandler storageFluidHandler, @Nullable Player player) {
		for (Direction dir : Direction.values()) {
			BlockPos offsetPos = pos.offset(dir.getNormal());
			if (player != null && !WorldHelper.playerMayInteract(player, level, offsetPos)) {
				continue;
			}

			boolean successful = WorldHelper.getBlockEntity(level, offsetPos)
					.map(be -> CapabilityHelper.<Boolean>getFromFluidHandler(be, dir.getOpposite(), fluidHandler -> {
						if (isInput()) {
							return fillFromFluidHandler(fluidHandler, storageFluidHandler, getMaxInOut());
						} else {
							return fillFluidHandler(fluidHandler, storageFluidHandler, getMaxInOut());
						}
					}, false)).orElse(false);
			if (successful) {
				return Optional.of(FLUID_HANDLER_INTERACTION_COOLDOWN_TIME);
			}
		}

		return Optional.empty();
	}

private Optional<Integer> interactWithWorld(Level level, BlockPos pos, IFluidHandler storageFluidHandler, @Nullable Entity entity) {
		Optional<Player> interactingPlayer = getInteractingPlayer(level, pos, entity);
		if (interactingPlayer.isEmpty()) {
			return Optional.empty();
		}

		Player player = interactingPlayer.get();
		if (isInput()) {
			return fillFromBlockInRange(level, pos, storageFluidHandler, player);
		} else {
			for (Direction dir : Direction.values()) {
				BlockPos offsetPos = pos.offset(dir.getNormal());
				if (placeFluidInWorld(level, storageFluidHandler, dir, offsetPos, player)) {
					return Optional.of(WORLD_INTERACTION_COOLDOWN_TIME);
				}
			}
		}
		return Optional.empty();
	}

private Optional<Player> getInteractingPlayer(Level level, BlockPos pos, @Nullable Entity entity) {
		if (entity instanceof Player player) {
			return Optional.of(player);
		}

		if (level instanceof ServerLevel serverLevel) {
			CoreFakePlayer fakePlayer = CoreFakePlayer.get(serverLevel);
			fakePlayer.setPosition(Vec3.atCenterOf(pos));
			return Optional.of(fakePlayer);
		}

		return Optional.empty();
	}

private boolean placeFluidInWorld(Level level, IFluidHandler storageFluidHandler, Direction dir, BlockPos offsetPos, Player player) {
		if (dir != Direction.UP) {
			for (int tank = 0; tank < storageFluidHandler.getTanks(); tank++) {
				FluidStack tankFluid = storageFluidHandler.getFluidInTank(tank);
				if (!tankFluid.isEmpty() && fluidFilterLogic.fluidMatches(tankFluid) && WorldHelper.playerMayInteract(player, offsetPos)
						&& isValidForFluidPlacement(level, offsetPos)
						&& FluidUtil.tryPlaceFluid(null, level, InteractionHand.MAIN_HAND, offsetPos, storageFluidHandler, tankFluid)) {
					return true;
				}
			}
		}
		return false;
	}

private boolean isValidForFluidPlacement(Level level, BlockPos offsetPos) {
		BlockState blockState = level.getBlockState(offsetPos);
		return blockState.isAir() || (!blockState.getFluidState().isEmpty() && !blockState.getFluidState().isSource());
	}

private Optional<Integer> fillFromBlockInRange(Level level, BlockPos basePos, IFluidHandler storageFluidHandler, Player player) {
		LinkedList<BlockPos> nextPositions = new LinkedList<>();
		Set<BlockPos> searchedPositions = new HashSet<>();
		nextPositions.add(basePos);

		while (!nextPositions.isEmpty()) {
			BlockPos pos = nextPositions.poll();
			if (fillFromBlock(level, pos, storageFluidHandler, player)) {
				return Optional.of((int) (Math.max(1, Math.sqrt(basePos.distSqr(pos))) * WORLD_INTERACTION_COOLDOWN_TIME));
			}

			for (Direction dir : Direction.values()) {
				BlockPos offsetPos = pos.offset(dir.getNormal());
				if (!searchedPositions.contains(offsetPos)) {
					searchedPositions.add(offsetPos);
					if (basePos.distSqr(offsetPos) < PUMP_IN_WORLD_RANGE_SQR) {
						nextPositions.add(offsetPos);
					}
				}
			}
		}
		return Optional.empty();
	}

private boolean fillFromBlock(Level level, BlockPos pos, IFluidHandler storageFluidHandler, Player player) {
		if (!WorldHelper.playerMayInteract(player, pos)) {
			return false;
		}

		FluidState fluidState = level.getFluidState(pos);
		if (!fluidState.isEmpty() && fluidState.isSource()) {
			BlockState state = level.getBlockState(pos);
			Block block = state.getBlock();
			IFluidHandler targetFluidHandler;
			if (block instanceof BucketPickup bucketPickup) {
				targetFluidHandler = new BucketPickupHandlerWrapper(player, bucketPickup, level, pos);
			} else {
				Optional<IFluidHandler> fluidHandler = FluidUtil.getFluidHandler(level, pos, null);
				if (fluidHandler.isEmpty()) {
					return false;
				}
				targetFluidHandler = fluidHandler.get();
			}
			return fillFromFluidHandler(targetFluidHandler, storageFluidHandler);
		}
		return false;
	}

private boolean handleFluidContainersInHandsOfNearbyPlayers(Level level, BlockPos pos, IFluidHandler storageFluidHandler) {
		AABB searchBox = new AABB(pos).inflate(PLAYER_SEARCH_RANGE);
		for (Player player : level.players()) {
			if (searchBox.contains(player.getX(), player.getY(), player.getZ()) && handleFluidContainerInHands(player, storageFluidHandler)) {
				return true;
			}
		}
		return false;
	}

private boolean handleFluidContainerInHands(Player player, IFluidHandler storageFluidHandler) {
		return handleFluidContainerInHand(storageFluidHandler, player, InteractionHand.MAIN_HAND)
				|| handleFluidContainerInHand(storageFluidHandler, player, InteractionHand.OFF_HAND);
	}

private boolean handleFluidContainerInHand(IFluidHandler storageFluidHandler, Player player, InteractionHand hand) {
		ItemStack itemInHand = player.getItemInHand(hand);
		if (itemInHand.getCount() != 1 || itemInHand == storageWrapper.getWrappedStorageStack()) {
			return false;
		}
		return CapabilityHelper.getFromFluidHandler(itemInHand, itemFluidHandler -> {
			if (isInput()) {
				return fillFromHand(player, hand, itemFluidHandler, storageFluidHandler);
			} else {
				return fillContainerInHand(player, hand, itemFluidHandler, storageFluidHandler);
			}
		}, false);
	}

private boolean fillContainerInHand(Player player, InteractionHand hand, IFluidHandlerItem itemFluidHandler, IFluidHandler storageFluidHandler) {
		boolean ret = fillFluidHandler(itemFluidHandler, storageFluidHandler);
		if (ret) {
			player.setItemInHand(hand, itemFluidHandler.getContainer());
		}
		return ret;
	}

private boolean fillFromHand(Player player, InteractionHand hand, IFluidHandlerItem itemFluidHandler, IFluidHandler storageFluidHandler) {
		if (fillFromFluidHandler(itemFluidHandler, storageFluidHandler)) {
			player.setItemInHand(hand, itemFluidHandler.getContainer());
			return true;
		}
		return false;
	}

