@Override
	public void inventoryTick(ItemStack stack, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (!(entity instanceof Player player) || player.isSpectator() || player.isDeadOrDying()) {
			return;
		}
		if (level instanceof ServerLevel serverLevel && LinkedStorageStackLifecycle.classifyEndpoint(stack) == LinkedStorageEndpointStackState.ENDPOINT) {
			Optional<IBackpackWrapper> primaryHost = BackpackLinkedStorageResolver.resolvePrimaryCanonicalHost(serverLevel, stack);
			boolean hasMobCatcher = primaryHost.map(host -> MobCatcherHandler.getBestUpgrade(host).isPresent()).orElse(false);
			boolean catcherChanged = stack.getOrDefault(ModDataComponents.LINKED_MOB_CATCHER, false) != hasMobCatcher;
			if (catcherChanged) {
				stack.set(ModDataComponents.LINKED_MOB_CATCHER, hasMobCatcher);
			}
			if (BackpackLinkedStorageResolver.synchronizeRenderProjection(serverLevel, stack) || catcherChanged) {
				player.inventoryMenu.broadcastChanges();
			}
			primaryHost.ifPresent(backpackWrapper -> {
				if (player instanceof ServerPlayer serverPlayer) {
					LinkedStorageJukeboxPlaybackAnchors.refreshPlayerAnchor(serverPlayer, stack);
				}
				if (!Config.SERVER.nerfsConfig.onlyWornBackpackTriggersUpgrades.get() || itemSlot <= -1) {
					backpackWrapper.getUpgradeHandler().getWrappersThatImplement(ITickableUpgrade.class)
							.forEach(upgrade -> upgrade.tick(player, player.level(), player.blockPosition()));
				}
			});
			super.inventoryTick(stack, level, entity, itemSlot, isSelected);
			return;
		}
		if (Config.SERVER.nerfsConfig.onlyWornBackpackTriggersUpgrades.get() && itemSlot > -1) {
			return;
		}
		IBackpackWrapper backpackWrapper = BackpackWrapper.fromStack(stack);
		backpackWrapper.getUpgradeHandler().getWrappersThatImplement(ITickableUpgrade.class).forEach(upgrade -> {
			if (level.isClientSide) {
				upgrade.clientTick(player, player.level(), player.blockPosition());
			} else {
				upgrade.tick(player, player.level(), player.blockPosition());
			}
		});
		super.inventoryTick(stack, level, entity, itemSlot, isSelected);
	}

public static void serverTick(Level level, BlockPos blockPos, BackpackBlockEntity backpackBlockEntity) {
		if (level.isClientSide) {
			return;
		}
		if (level instanceof ServerLevel serverLevel && LinkedStorageStackLifecycle
				.classifyEndpoint(backpackBlockEntity.backpackWrapper.getBackpack()) == LinkedStorageEndpointStackState.ENDPOINT) {
			BackpackLinkedStorageResolver.resolvePrimaryCanonicalHost(serverLevel, backpackBlockEntity.backpackWrapper.getBackpack())
					.ifPresent(backpackWrapper -> {
						backpackWrapper.getUpgradeHandler().getWrappersThatImplement(ITickableUpgrade.class)
								.forEach(upgrade -> upgrade.tick(null, level, blockPos));
					});
			return;
		}
		backpackBlockEntity.backpackWrapper.getUpgradeHandler().getWrappersThatImplement(ITickableUpgrade.class)
				.forEach(upgrade -> upgrade.tick(null, level, blockPos));
	}

